"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[49541],{3331:(e,i,a)=>{a.d(i,{R:()=>c,x:()=>t});var o=a(36672);const n={},r=o.createContext(n);function c(e){const i=o.useContext(r);return o.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function t(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:c(e.components),o.createElement(r.Provider,{value:i},e.children)}},71299:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>s,contentTitle:()=>t,default:()=>y,frontMatter:()=>c,metadata:()=>o,toc:()=>w});const o=JSON.parse('{"id":"2023/04/06","title":"2023-04-06","description":"Remembering Bob Lee","source":"@site/i18n/pl/docusaurus-plugin-content-docs/current/2023/04/06.md","sourceDirName":"2023/04","slug":"/2023/04/06","permalink":"/pl/2023/04/06","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/pl/docusaurus-plugin-content-docs//current/2023/04/06.md","tags":[],"version":"current","frontMatter":{"localized_date":"6 kwietnia 2023","top_news":"Remembering Bob Lee"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-07","permalink":"/pl/2023/04/07"},"next":{"title":"2023-04-05","permalink":"/pl/2023/04/05"}}');var n=a(23420),r=a(3331);const c={localized_date:"6 kwietnia 2023",top_news:"Remembering Bob Lee"},t="2023-04-06",s={},w=[{value:"Remembering Bob Lee",id:"remembering-bob-lee",level:2},{value:"Bob Lee, by\u0142y CTO of Square, zmar\u0142 po tym, jak zosta\u0142 zasztyletowany w San Francisco",id:"bob-lee-by\u0142y-cto-of-square-zmar\u0142-po-tym-jak-zosta\u0142-zasztyletowany-w-san-francisco",level:2},{value:"Powiedz iOS pozwala przewo\u017anikom dodawa\u0107 sieci WiFi, kt\xf3rych nie mo\u017cna powstrzyma\u0107 przed do\u0142\u0105czeniem",id:"powiedz-ios-pozwala-przewo\u017anikom-dodawa\u0107-sieci-wifi-kt\xf3rych-nie-mo\u017cna-powstrzyma\u0107-przed-do\u0142\u0105czeniem",level:2},{value:"Podstawy uczenia g\u0142\u0119bokiego do stabilnej dyfuzji",id:"podstawy-uczenia-g\u0142\u0119bokiego-do-stabilnej-dyfuzji",level:2},{value:"CAN Injection: Kradzie\u017c samochodu bez klucza",id:"can-injection-kradzie\u017c-samochodu-bez-klucza",level:2},{value:"In\u017cynierowie Firefoxa odkrywaj\u0105 b\u0142\u0105d w Windows Defenderze, kt\xf3ry powoduje wysokie zu\u017cycie procesora",id:"in\u017cynierowie-firefoxa-odkrywaj\u0105-b\u0142\u0105d-w-windows-defenderze-kt\xf3ry-powoduje-wysokie-zu\u017cycie-procesora",level:2},{value:"Segment Anything Model (SAM) mo\u017ce &quot;wyci\u0105\u0107&quot; dowolny obiekt z obrazu",id:"segment-anything-model-sam-mo\u017ce-wyci\u0105\u0107-dowolny-obiekt-z-obrazu",level:2},{value:"Bitcoin whitepaper jest ukryty w ka\u017cdej kopii macOS",id:"bitcoin-whitepaper-jest-ukryty-w-ka\u017cdej-kopii-macos",level:2},{value:"Former Square CTO Bob Lee Stabbed to Death in Downtown San Francisco",id:"former-square-cto-bob-lee-stabbed-to-death-in-downtown-san-francisco",level:2},{value:"The case for banning children from social media",id:"the-case-for-banning-children-from-social-media",level:2},{value:"Dang b\u0119dzie mia\u0142 wkr\xf3tce 65,535 punkt\xf3w karmy",id:"dang-b\u0119dzie-mia\u0142-wkr\xf3tce-65535-punkt\xf3w-karmy",level:2},{value:"Sieci Neuronowe: Od zera do bohatera",id:"sieci-neuronowe-od-zera-do-bohatera",level:2},{value:"Sztuczka na osi\u0105gni\u0119cie przep\u0142ywu: Zostaw swoj\u0105 prac\u0119 zepsut\u0105",id:"sztuczka-na-osi\u0105gni\u0119cie-przep\u0142ywu-zostaw-swoj\u0105-prac\u0119-zepsut\u0105",level:2},{value:"Czy pami\u0119\u0107 RAM jest wymazywana przed u\u017cyciem w innym kontenerze LXC?",id:"czy-pami\u0119\u0107-ram-jest-wymazywana-przed-u\u017cyciem-w-innym-kontenerze-lxc",level:2},{value:"Perspektywa: Open Source WebAssembly-Powered BI",id:"perspektywa-open-source-webassembly-powered-bi",level:2},{value:"Grid World",id:"grid-world",level:2},{value:"Tokenizer OpenAI",id:"tokenizer-openai",level:2},{value:"Tabloid - J\u0119zyk programowania nag\u0142\xf3wk\xf3w clickbaitowych",id:"tabloid---j\u0119zyk-programowania-nag\u0142\xf3wk\xf3w-clickbaitowych",level:2},{value:"GPT4 symuluje serwer FTP na ftp.disney.com",id:"gpt4-symuluje-serwer-ftp-na-ftpdisneycom",level:2},{value:"U\u017cycie mmap, aby LLaMA \u0142adowa\u0142a si\u0119 szybciej",id:"u\u017cycie-mmap-aby-llama-\u0142adowa\u0142a-si\u0119-szybciej",level:2}];function z(e){const i={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(i.header,{children:(0,n.jsx)(i.h1,{id:"2023-04-06",children:"2023-04-06"})}),"\n",(0,n.jsx)(i.h2,{id:"remembering-bob-lee",children:"Remembering Bob Lee"}),"\n",(0,n.jsx)(i.p,{children:"Spo\u0142eczno\u015b\u0107 technologiczna op\u0142akuje strat\u0119 Boba Lee, znanej postaci w bran\u017cy. Lee by\u0142 or\u0119downikiem Javy, pracowa\u0142 w Google i Square, by\u0142 znany ze swojej pracy nad frameworkiem Guice dependency injection. By\u0142 r\xf3wnie\u017c wsp\xf3\u0142za\u0142o\u017cycielem Android Alliance, inicjatywy maj\u0105cej na celu promowanie innowacji w ekosystemie Androida. Wk\u0142ad Lee w \u015bwiat technologii by\u0142 powszechnie uznawany i b\u0119dzie go bardzo brakowa\u0142o jego kolegom i r\xf3wie\u015bnikom. Wiele os\xf3b podzieli\u0142o si\u0119 swoimi kondolencjami w mediach spo\u0142eczno\u015bciowych, wspominaj\u0105c Lee jako mentora i przyjaciela, kt\xf3ry zawsze znajdowa\u0142 czas dla innych. Spoczywaj w pokoju, Bob Lee."}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35457341",children:"Discussion Service"}),".\nOdszed\u0142 Bob Lee, wsp\xf3\u0142tw\xf3rca bibliotek Guice i Java, znany ze swoich umiej\u0119tno\u015bci technicznych, \u017cyczliwo\u015bci i pokory. Jego \u015bmier\u0107 pozostawi\u0142a spo\u0142eczno\u015b\u0107 technologiczn\u0105 w \u017ca\u0142obie i sk\u0142oni\u0142a wiele os\xf3b do podzielenia si\u0119 swoimi wspomnieniami i anegdotami na jego temat. Dziedzictwo innowacji i pasji Lee zainspirowa\u0142o wielu, a jego wk\u0142ad w bran\u017c\u0119 b\u0119dzie pomini\u0119ty. Podczas gdy niekt\xf3re komentarze odbiega\u0142y od tematu, wi\u0119kszo\u015b\u0107 dzieli\u0142a si\u0119 pozytywnymi przemy\u015bleniami i do\u015bwiadczeniami na temat Boba."]}),"\n",(0,n.jsx)(i.h2,{id:"bob-lee-by\u0142y-cto-of-square-zmar\u0142-po-tym-jak-zosta\u0142-zasztyletowany-w-san-francisco",children:"Bob Lee, by\u0142y CTO of Square, zmar\u0142 po tym, jak zosta\u0142 zasztyletowany w San Francisco"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php",children:"Original"}),".\nBob Lee, tw\xf3rca Cash App jako Chief Technology Officer w Square, zosta\u0142 zidentyfikowany jako cz\u0142owiek, kt\xf3ry zosta\u0142 zabity w San Francisco z powodu pchni\u0119cia no\u017cem; wydarzenie wstrz\u0105sn\u0119\u0142o \u015bwiatem technologii, z lud\u017ami reaguj\u0105cymi na nag\u0142e wiadomo\u015bci. Policja nie dokona\u0142a \u017cadnych aresztowa\u0144 ani nie ujawni\u0142a \u017cadnych informacji dotycz\u0105cych ewentualnych podejrzanych. Lee mia\u0142 43 lata, by\u0142 za\u0142o\u017cycielem Cash App, a w chwili \u015bmierci pracowa\u0142 jako Chief Product Officer w MobileCoin."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35448899",children:"Discussion Service"}),".\nBy\u0142y CTO of Square, Bob Lee, zabity w San Francisco wywo\u0142uje dyskusj\u0119 na temat przest\u0119pczo\u015bci i zarz\u0105dzania. Komentarze dotycz\u0105 nier\xf3wno\u015bci maj\u0105tkowych, bezdomno\u015bci, gentryfikacji i potencjalnych rozwi\u0105za\u0144. Dyskusja stawia pod znakiem zapytania systemy polityczne i nierzetelne statystyki przest\u0119pczo\u015bci w ameryka\u0144skich miastach. U\u017cytkownicy omawiaj\u0105 potencjalne przyczyny przest\u0119pczo\u015bci, w tym masow\u0105 migracj\u0119, nier\xf3wno\u015bci maj\u0105tkowe, wp\u0142yw system\xf3w s\u0105downiczych i brak reakcji policji. Por\xf3wnywanie przest\u0119pczo\u015bci pomi\u0119dzy r\xf3\u017cnymi krajami lub kulturami nie jest pomocne. Problem przest\u0119pczo\u015bci jest z\u0142o\u017cony i nie wynika z \u017cadnego pojedynczego czynnika."]}),"\n",(0,n.jsx)(i.h2,{id:"powiedz-ios-pozwala-przewo\u017anikom-dodawa\u0107-sieci-wifi-kt\xf3rych-nie-mo\u017cna-powstrzyma\u0107-przed-do\u0142\u0105czeniem",children:"Powiedz iOS pozwala przewo\u017anikom dodawa\u0107 sieci WiFi, kt\xf3rych nie mo\u017cna powstrzyma\u0107 przed do\u0142\u0105czeniem"}),"\n",(0,n.jsx)(i.p,{children:'System operacyjny iOS pozwala przewo\u017anikom dodawa\u0107 sieci WiFi, z przy\u0142\u0105czenia do kt\xf3rych u\u017cytkownicy nie mog\u0105 zrezygnowa\u0107. Ta funkcja wywo\u0142uje niepok\xf3j w\u015br\xf3d u\u017cytkownik\xf3w iPhone\'a, kt\xf3rzy maj\u0105 ograniczone plany danych lub obawy o prywatno\u015b\u0107. Funkcja ma pom\xf3c przewo\u017anikom uruchomi\u0107 hotspoty WiFi, ale pozwala im r\xf3wnie\u017c doda\u0107 publiczne sieci WiFi, z kt\xf3rymi u\u017cytkownicy nie\u015bwiadomie si\u0119 \u0142\u0105cz\u0105, potencjalnie zbieraj\u0105c wra\u017cliwe dane. U\u017cytkownicy maj\u0105 ograniczone opcje, aby wy\u0142\u0105czy\u0107 funkcj\u0119, w tym wy\u0142\u0105czenie WiFi ca\u0142kowicie lub wybieraj\u0105c "Zapomnij t\u0119 sie\u0107" za ka\u017cdym razem, gdy go spotka\u0107. Niekt\xf3rzy u\u017cytkownicy wzywaj\u0105 Apple do dodania wi\u0119kszej kontroli nad t\u0105 funkcj\u0105, podczas gdy inni sugeruj\u0105 u\u017cycie VPN do ochrony swoich danych.'}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35447486",children:"Discussion Service"}),".\niOS 16.4 pozwala przewo\u017anikom dodawa\u0107 zarz\u0105dzane sieci do urz\u0105dze\u0144, obni\u017ca\u0107 koszty kom\xf3rkowe i zapobiega\u0107 wy\u0142\u0105czeniu auto-join, bez aktualnego sposobu na usuni\u0119cie tych sieci innych ni\u017c resetowanie ustawie\u0144 sieciowych. U\u017cytkownicy zg\u0142aszaj\u0105 T-Mobile kradzie\u017c danych i Wingman w locie sieci nie wy\u0142\u0105czaj\u0105c, i wyrazi\u0107 szok na przewo\u017anik\xf3w dyktowania po\u0142\u0105cze\u0144 WiFi bez odwo\u0142ania u\u017cytkownika. Debata trwa, jak uzyska\u0107 pe\u0142n\u0105 kontrol\u0119 nad urz\u0105dzeniem, z niekt\xf3rych u\u017cytkownik\xf3w zalecaj\u0105cych GrapheneOS dla aktualizacji zabezpiecze\u0144. Carrier WiFi hotspoty s\u0105 krytykowane za zak\u0142\xf3canie po\u0142\u0105cze\u0144 do lokalnych urz\u0105dze\u0144, a niekt\xf3re znale\u017a\u0107 funkcj\u0119 przydatn\u0105 w zat\u0142oczonych obszarach."]}),"\n",(0,n.jsx)(i.h2,{id:"podstawy-uczenia-g\u0142\u0119bokiego-do-stabilnej-dyfuzji",children:"Podstawy uczenia g\u0142\u0119bokiego do stabilnej dyfuzji"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://course.fast.ai/Lessons/part2.html",children:"Original"}),'.\n"Practical Deep Learning for Coders - Part 2" to kurs sk\u0142adaj\u0105cy si\u0119 z ponad 30 godzin tre\u015bci wideo, kt\xf3ry obejmuje pokrycie algorytmu Stable Diffusion od podstaw, \u015bci\u015ble wsp\xf3\u0142pracuj\u0105c z ekspertami z Stable.ai i Hugging Face. Kurs zapewnia rygorystyczne pokrycie najnowszych technik i wykracza nawet poza to, co zawiera Stable Diffusion, co czyni go \u015bwietnym celem nauki z wielu powod\xf3w, jednak aby uzyska\u0107 jak najwi\u0119cej z tego kursu, powiniene\u015b by\u0107 do\u015b\u0107 pewnym praktykiem g\u0142\u0119bokiego uczenia. Przez ca\u0142y kurs, b\u0119dziemy bada\u0107 metody dyfuzji, wdro\u017cy\u0107 w\u0142asne modele od podstaw, opanowa\u0107 koncepcje Pythona i PyTorch do wdro\u017cenia naszych modeli. B\u0119dziemy obejmowa\u0107 fundamenty dyfuzji, optymalizatory g\u0142\u0119bokiego uczenia, koncepcje Pythona, podstawowe podstawy, generowanie liczb pseudolosowych, architektury sieci neuronowych, architektury generatywne, transformatory i mieszane szkolenie precyzji.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35449831",children:"Discussion Service"}),".\n'Deep Learning Foundations to Stable Diffusion' bada nowoczesne modelowanie generatywne, podczas gdy niekt\xf3rzy zalecaj\u0105 skupienie si\u0119 na marketingu. Kurs g\u0142\u0119bokiego uczenia Fast.ai tworzy ramy programistyczne od podstaw i jest zalecany dla ka\u017cdego zainteresowanego. Trwa debata wok\xf3\u0142 potencjalnych zagro\u017ce\u0144 zwi\u0105zanych z zaawansowan\u0105 AI oraz znaczenia regulacji i rozwa\u017ca\u0144 etycznych. Komentatorzy sugeruj\u0105 zakazanie wyj\u015bcia AI, ale nie jest to d\u0142ugoterminowe rozwi\u0105zanie, chyba \u017ce wszystkie kraje to zrobi\u0105. Kurs FastAI nie ma \u017cadnych politycznie lub religijnie stronniczych wypowiedzi, a jego tre\u015b\u0107 jest uwa\u017cana za najwy\u017cszej klasy. Kurs jest dost\u0119pny dla ka\u017cdego z podstawow\u0105 matematyk\u0105 w szkole \u015bredniej i obejmuje zaawansowane koncepcje."]}),"\n",(0,n.jsx)(i.h2,{id:"can-injection-kradzie\u017c-samochodu-bez-klucza",children:"CAN Injection: Kradzie\u017c samochodu bez klucza"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://kentindell.github.io/2023/04/03/can-injection/",children:"Original"}),".\nZ\u0142odzieje samochod\xf3w u\u017cywaj\u0105 nowej techniki zwanej CAN Injection do omini\u0119cia system\xf3w inteligentnych kluczy w nowoczesnych samochodach poprzez wykorzystanie luk w protokole komunikacyjnym magistrali CAN. Wyrafinowane systemy zabezpiecze\u0144 samochod\xf3w, w tym immobilizery silnika, sta\u0142y si\u0119 podatne na ataki. Z\u0142odzieje u\u017cywaj\u0105 urz\u0105dzenia o nazwie CAN Injector do kradzie\u017cy samochod\xf3w bez kluczyka poprzez wstrzykiwanie fa\u0142szywych wiadomo\u015bci do wewn\u0119trznego systemu komunikacji samochodu. Urz\u0105dzenie kosztuje 10 dolar\xf3w i zawiera uk\u0142ad scalony PIC18F, wst\u0119pnie zaprogramowany firmware, transceiver i dodatkowy obw\xf3d. Szybka poprawka lub kryptograficzne wiadomo\u015bci mog\u0105 pokona\u0107 CAN Injector. Ian Haken nakre\u015bla kilka sposob\xf3w, w jakie producenci samochod\xf3w mogliby pom\xf3c w zabezpieczeniu samochod\xf3w, ale przest\u0119pcze wykorzystanie tej techniki jest powszechne. Jest to problem og\xf3lnobran\u017cowy, kt\xf3ry wymaga aktualizacji oprogramowania ECU, aby pokona\u0107 z\u0142odziei."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35452963",children:"Discussion Service"}),".\nTechnika kradzie\u017cy samochod\xf3w bez klucza znana jako CAN Injection zosta\u0142a wyr\xf3\u017cniona na Hacker News. Konsumenci powinni uwa\u017ca\u0107 na szyfrowanie lub podpisywanie magistrali CAN, poniewa\u017c mo\u017ce to ograniczy\u0107 narz\u0119dzia diagnostyczne innych firm, zwi\u0119kszaj\u0105c koszty naprawy. Magistrala CAN kontroluje wiele funkcji pojazdu, a producenci pojazd\xf3w bezwzgl\u0119dnie optymalizuj\u0105 koszty. Producenci samochod\xf3w maj\u0105 wymogi prawne, aby oddzieli\u0107 si\u0119 od dealer\xf3w, ale niekt\xf3re komentarze krytykuj\u0105 ich przestrzeganie ducha prawa. Marki samochod\xf3w premium stosuj\u0105 r\xf3\u017cne \u015brodki bezpiecze\u0144stwa, aby zapobiec w\u0142amaniom do samochod\xf3w, w tym immobilizery z odpowiednimi protoko\u0142ami kryptograficznymi do uwierzytelniania wiadomo\u015bci start-release i podpisane ramki CAN/FlexRay/Ethernet, aby zapobiec spoofingowi wiadomo\u015bci. Tanie samochody s\u0105 celem atak\xf3w, poniewa\u017c \u0142atwo je ukra\u015b\u0107, natomiast drogie samochody s\u0105 celem brutalnych kradzie\u017cy. Opisany w artykule exploit m\xf3g\u0142by zosta\u0107 zastosowany do niemal ka\u017cdego niepod\u0142\u0105czonego do sieci pojazdu wyprodukowanego w ostatniej dekadzie. Zastosowanie magistrali CAN w krytycznych systemach, takich jak lotnictwo i motoryzacja, wynika z prostoty okablowania i op\u0142acalno\u015bci."]}),"\n",(0,n.jsx)(i.h2,{id:"in\u017cynierowie-firefoxa-odkrywaj\u0105-b\u0142\u0105d-w-windows-defenderze-kt\xf3ry-powoduje-wysokie-zu\u017cycie-procesora",children:"In\u017cynierowie Firefoxa odkrywaj\u0105 b\u0142\u0105d w Windows Defenderze, kt\xf3ry powoduje wysokie zu\u017cycie procesora"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918#c82",children:"Orygina\u0142"}),".\nN/A (Ten tekst nie jest zwi\u0105zany z tematem)."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35458746",children:"Discussion Service"}),".\nIn\u017cynierowie Firefoksa znale\u017ali b\u0142\u0105d w Windows Defenderze powoduj\u0105cy zu\u017cycie procesora w przegl\u0105darce Mozilli. Microsoft wypuszcza \u0142atk\u0119, kt\xf3ra ma to naprawi\u0107. Inne produkty AV r\xf3wnie\u017c mog\u0105 powodowa\u0107 problemy z wykorzystaniem procesora. Firefox wykonuje wi\u0119cej wywo\u0142a\u0144 systemowych ni\u017c Chrome ze wzgl\u0119d\xf3w bezpiecze\u0144stwa. Por\xf3wnanie pokazuje, \u017ce w niekt\xf3rych testach Firefox dzia\u0142a szybciej ni\u017c Chrome. Eksperci omawiaj\u0105 ograniczenia Defendera, sugeruj\u0105 sandboxing i sprz\u0119towe MFA. U\u017cytkownicy dyskutuj\u0105 o skuteczno\u015bci Defendera w por\xf3wnaniu z oprogramowaniem AV innych firm. Niekt\xf3rzy u\u017cytkownicy zg\u0142aszaj\u0105 problemy z Defenderem powoduj\u0105cym powolny dost\u0119p do systemu plik\xf3w."]}),"\n",(0,n.jsx)(i.h2,{id:"segment-anything-model-sam-mo\u017ce-wyci\u0105\u0107-dowolny-obiekt-z-obrazu",children:'Segment Anything Model (SAM) mo\u017ce "wyci\u0105\u0107" dowolny obiekt z obrazu'}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://segment-anything.com/",children:"Original"}),".\nSegment Anything Model (SAM) opracowany przez Meta AI mo\u017ce wyodr\u0119bni\u0107 dowolny obiekt na obrazie z du\u017c\u0105 dok\u0142adno\u015bci\u0105. Mo\u017ce on z powodzeniem identyfikowa\u0107 i segmentowa\u0107 obiekty, nawet je\u015bli s\u0105 one cz\u0119\u015bciowo widoczne lub zas\u0142oni\u0119te. SAM stanowi ulepszenie wcze\u015bniej opracowanych modeli, kt\xf3re opiera\u0142y si\u0119 na wskaz\xf3wkach dotycz\u0105cych lokalizacji lub istotnych obiekt\xf3w. Zamiast korzysta\u0107 z tych wskaz\xf3wek, SAM stosuje meta-uczenie, wykorzystuj\u0105c uczenie istniej\u0105cego modelu, aby by\u0107 w stanie wykry\u0107 ma\u0142e, nieobiektywne zbiory danych lub niewidoczne obiekty. SAM mo\u017ce by\u0107 wykorzystywany w praktycznych zastosowaniach, takich jak edycja obraz\xf3w, jak r\xf3wnie\u017c w badaniach w dziedzinie wizji komputerowej."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35455566",children:"Discussion Service"}),'.\nSAM firmy Meta AI umo\u017cliwia generowanie masek w czasie rzeczywistym w celu "wyci\u0119cia" dowolnego obiektu z obrazu. Licencjonowanie modelu i imponuj\u0105ce mo\u017cliwo\u015bci wnioskowania mog\u0105 uczyni\u0107 go popularnym w\u015br\xf3d ekspert\xf3w technicznych. Problemy obejmuj\u0105 wolniejsz\u0105 pr\u0119dko\u015b\u0107 z modelem RTX 2080ti 11GB i ograniczon\u0105 precyzj\u0119 z przezroczystymi obiektami. Niekt\xf3rzy postrzegaj\u0105 strategi\u0119 wydawnicz\u0105 Meta AI jako cz\u0119\u015b\u0107 impulsu do przyj\u0119cia AR. U\u017cytkownicy chwal\u0105 redukcj\u0119 koszt\xf3w adnotacji danych SAM, ale krytykuj\u0105 jego szybko\u015b\u0107 i por\xf3wnuj\u0105 go do iOS. Rozw\xf3j mo\u017ce mie\u0107 r\xf3wnie\u017c potencjaln\u0105 aplikacj\u0119 kamery bezpiecze\u0144stwa i integracj\u0119 AdobeAI.']}),"\n",(0,n.jsx)(i.h2,{id:"bitcoin-whitepaper-jest-ukryty-w-ka\u017cdej-kopii-macos",children:"Bitcoin whitepaper jest ukryty w ka\u017cdej kopii macOS"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://waxy.org/2023/04/the-bitcoin-whitepaper-is-hidden-in-every-modern-copy-of-macos/",children:"Orygina\u0142"}),'.\nKopia PDF Bitcoin whitepaper Satoshiego Nakamoto zosta\u0142a odkryta w ka\u017cdej nowoczesnej kopii macOS od Mojave w 2018 roku i mo\u017cna uzyska\u0107 do niej dost\u0119p poprzez przyk\u0142adowy dokument w narz\u0119dziu Image Capture. Whitepaper jest u\u017cywany jako przyk\u0142adowy dokument dla urz\u0105dzenia o nazwie "Virtual Scanner II", kt\xf3ry jest domy\u015blnie ukryty lub nie jest zainstalowany dla wszystkich. Chocia\u017c pow\xf3d jego w\u0142\u0105czenia jest nadal niejasny, m\xf3g\u0142 to by\u0107 wygodny i lekki wielostronicowy PDF do cel\xf3w testowych. W sieci dost\u0119pnych jest bardzo ma\u0142o informacji na temat Virtual Scanner II lub w\u0142\u0105czenia whitepapera do macOS.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35461011",children:"Discussion Service"}),".\nBia\u0142a ksi\u0119ga Bitcoina jest ukryta w ka\u017cdej kopii macOS od 2019 roku; spekulacje otaczaj\u0105, dlaczego jest w\u0142\u0105czona, a u\u017cytkownicy ostrzegaj\u0105 przed wydobywaniem na iPhone'ach. Suma haszowa pasuje do oryginalnej wersji, ale teorie r\xf3\u017cni\u0105 si\u0119 co do tego, dlaczego jest do\u0142\u0105czona. Pojawi\u0142y si\u0119 skargi dotycz\u0105ce poparcia schematu Ponzi, ale u\u017cytkownicy wyja\u015bniaj\u0105, \u017ce jest on ukryty. Apple mog\u0142o w\u0142\u0105czy\u0107 go dla wygody, ale post wywo\u0142uje dialog na temat wp\u0142ywu Bitcoina. U\u017cytkownicy komentuj\u0105 zdj\u0119cie u\u017cyte w artykule, rozmiar pliku PDF i utrat\u0119 artystycznej zabawy przez technologi\u0119."]}),"\n",(0,n.jsx)(i.h2,{id:"former-square-cto-bob-lee-stabbed-to-death-in-downtown-san-francisco",children:"Former Square CTO Bob Lee Stabbed to Death in Downtown San Francisco"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/",children:"Original"}),".\nBy\u0142y Square CTO Bob Lee zosta\u0142 zasztyletowany na \u015bmier\u0107 w Downtown San Francisco wed\u0142ug The Standard. Lee by\u0142 Chief Product Officer w MobileCoin, firmie kryptowalutowej w San Francisco i ukochanym cz\u0142onkiem spo\u0142eczno\u015bci rozwoju oprogramowania i technologii w Bay Area. SFPD nie ujawni\u0142o \u017cadnych dodatkowych szczeg\xf3\u0142\xf3w ani to\u017csamo\u015bci ofiary, a tak\u017ce prosi o naocznych \u015bwiadk\xf3w i nagrania wideo dla ich dochodzenia. Od 2 kwietnia w San Francisco dosz\u0142o do 12 zab\xf3jstw, o dwa wi\u0119cej ni\u017c w tym samym okresie ubieg\u0142ego roku. The Standard opisuje wa\u017cne historie, w tym kwestie zwi\u0105zane z wymiarem sprawiedliwo\u015bci w San Francisco, a tak\u017ce dostarcza biuletyn\xf3w i kompleksowy przegl\u0105d polityki i kultury San Francisco."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35452426",children:"Discussion Service"}),".\nBy\u0142y Square CTO Bob Lee zasztyletowany na \u015bmier\u0107 w San Francisco; komentarze odnosz\u0105 si\u0119 do nowych szczeg\xf3\u0142\xf3w."]}),"\n",(0,n.jsx)(i.h2,{id:"the-case-for-banning-children-from-social-media",children:"The case for banning children from social media"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.newyorker.com/news/our-columnists/the-case-for-banning-children-from-social-media",children:"Orygina\u0142"}),".\nDebata na temat zakazu korzystania przez dzieci z medi\xf3w spo\u0142eczno\u015bciowych trwa z powodu obaw o uzale\u017cnienie i negatywizm. Niekt\xf3re ustawy zosta\u0142y uchwalone w celu ograniczenia dost\u0119pu nieletnich do stron medi\xf3w spo\u0142eczno\u015bciowych i usuni\u0119cia funkcji uzale\u017cniaj\u0105cych, ale to podnosi implikacje w zakresie wolno\u015bci obywatelskiej i ogranicza dost\u0119p do wiadomo\u015bci i r\xf3\u017cnych perspektyw, stawiaj\u0105c pytanie, jak media spo\u0142eczno\u015bciowe powinny by\u0107 traktowane. Podczas gdy s\u0105dy zlikwidowa\u0142y zabezpieczenia online dla bezpiecze\u0144stwa dzieci, tworzenie komunikat\xf3w przeciw uzale\u017cnieniom i ograniczenia prawne stanowi\u0105 potencjalny konflikt z prawami do pierwszej poprawki, a rodzice mog\u0105 by\u0107 zmuszeni do uciekania si\u0119 do fizycznego usuwania ekran\xf3w. Ochrona dzieci online jest debat\u0105 polityczn\u0105 i kulturow\u0105, pozostawiaj\u0105c niewielkie zaufanie do zdolno\u015bci rz\u0105du do regulowania firm z bran\u017cy medi\xf3w spo\u0142eczno\u015bciowych."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35447588",children:"Discussion Service"}),".\nJeden z artyku\u0142\xf3w opowiada si\u0119 za zakazem korzystania z medi\xf3w spo\u0142eczno\u015bciowych przez osoby poni\u017cej 18 roku \u017cycia ze wzgl\u0119du na potencjalne uzale\u017cnienie od narkotyk\xf3w; regulowanie takich tre\u015bci sprawia trudno\u015bci. Debata na temat definicji i wp\u0142ywu reklam skierowanych do dzieci budzi obawy dotycz\u0105ce regulacji reklamy. Podnoszony jest szkodliwy wp\u0142yw medi\xf3w spo\u0142eczno\u015bciowych na zdrowie psychiczne i rozw\xf3j osobisty, co wywo\u0142uje sugestie dotycz\u0105ce zakazu korporacyjnych medi\xf3w spo\u0142eczno\u015bciowych i algorytmicznych kana\u0142\xf3w. Og\xf3lny zakaz korzystania z medi\xf3w spo\u0142eczno\u015bciowych nie jest postrzegany jako rozwi\u0105zanie; potrzebne jest zniuansowane podej\u015bcie. U\u017cytkownicy Discussion Service dyskutuj\u0105 nad skutecznymi sposobami ograniczenia czasu sp\u0119dzanego na ekranie i przeciwdzia\u0142ania negatywnym skutkom. Debata skupia si\u0119 na znalezieniu r\xf3wnowagi mi\u0119dzy wolno\u015bci\u0105 jednostki a odpowiedzialno\u015bci\u0105 spo\u0142eczn\u0105. Obawy dotycz\u0105ce kontroli medi\xf3w spo\u0142eczno\u015bciowych i uwalniania dopaminy w m\xf3zgu sk\u0142aniaj\u0105 do dyskusji na temat zakazu korzystania z medi\xf3w spo\u0142eczno\u015bciowych zasilanych algorytmami. Wykonalno\u015b\u0107 i potencjalna ingerencja w prywatno\u015b\u0107 s\u0105 podkre\u015blane jako obawy dotycz\u0105ce obowi\u0105zkowego sprawdzania to\u017csamo\u015bci dla kont w mediach spo\u0142eczno\u015bciowych. Nie om\xf3wiono \u017cadnej nowej technologii ani du\u017cego wydania."]}),"\n",(0,n.jsx)(i.h2,{id:"dang-b\u0119dzie-mia\u0142-wkr\xf3tce-65535-punkt\xf3w-karmy",children:"Dang b\u0119dzie mia\u0142 wkr\xf3tce 65,535 punkt\xf3w karmy"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://news.ycombinator.com/user?id=dang",children:"Original"}),".\nOczekuje si\u0119, \u017ce u\u017cytkownik Discussion Service 'dang' osi\u0105gnie wkr\xf3tce 65 535 punkt\xf3w karmy, co jest maksymalnym limitem ze wzgl\u0119du na u\u017cycie przez system podpisanej 16-bitowej liczby ca\u0142kowitej."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35460732",children:"Discussion Service"}),".\nDaniel Gackle, AKA Dang, wkr\xf3tce osi\u0105gnie 65 535 punkt\xf3w karmy. Sekcja komentarzy wype\u0142niona jest pochwa\u0142ami dla pracy Danga. U\u017cytkownicy spekuluj\u0105, czy karma si\u0119 przewr\xf3ci i dyskutuj\u0105 o zmianie na 32-bitowe int. Styl moderacji i zaanga\u017cowanie Y Combinatora s\u0105 kwestionowane. Osi\u0105ganie wysokiej karmy postrzegane jest jako spos\xf3b na okazanie uznania dla pracy Danga. Osi\u0105gni\u0119cie wy\u017cszego poziomu karmy pozwala na dodatkowe mo\u017cliwo\u015bci na Discussion Service, takie jak upvoting/downvoting."]}),"\n",(0,n.jsx)(i.h2,{id:"sieci-neuronowe-od-zera-do-bohatera",children:"Sieci Neuronowe: Od zera do bohatera"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://karpathy.ai/zero-to-hero.html",children:"Original"}),'.\nKurs "Neural Networks: Zero to Hero" autorstwa Andreja Karpathy\'ego uczy budowania sieci neuronowych od podstaw w kodzie. Kurs zaczyna si\u0119 od podstaw backpropagacji i przechodzi do nowoczesnych g\u0142\u0119bokich sieci neuronowych, takich jak GPT. Kurs koncentruje si\u0119 na modelach j\u0119zykowych, poniewa\u017c s\u0105 one doskona\u0142ym miejscem do nauki g\u0142\u0119bokiego uczenia si\u0119. Wymagania wst\u0119pne obejmuj\u0105 solidne programowanie i matematyk\u0119 intro-level. Kurs obejmuje budow\u0119 micrograd, makemore, MLP i nurkowanie w niekt\xf3rych wewn\u0119trznych MLP. Zostanie Backprop Ninja i budowa WaveNet s\u0105 r\xf3wnie\u017c omawiane. Kurs ko\u0144czy si\u0119 budow\u0105 GPT. Filmy dostarczaj\u0105 wyja\u015bnie\u0144 krok po kroku i skupiaj\u0105 si\u0119 na budowaniu kompetencji i intuicji wok\xf3\u0142 tego, jak optymalizowane s\u0105 sieci neuronowe. Kurs zaleca widz\xf3w ogl\u0105da\u0107 wcze\u015bniejsze filmy makemore, aby by\u0107 wygodne z ram autoregresywnego modelowania j\u0119zyka i podstawy tensor\xf3w i PyTorch nn.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35459031",children:"Discussion Service"}),".\nKurs Andreja Karpathy'ego 'Neural Networks: Zero to Hero' kurs zdobywa ponad 300 punkt\xf3w na Hacker News w 6 godzin. U\u017cytkownicy Discussion Service chwal\u0105 jego styl nauczania i polecaj\u0105 kodowanie po obejrzeniu film\xf3w. Jego kurs ML prowadzony przez r\xf3wie\u015bnik\xf3w otrzymuje pozytywne opinie, mimo \u017ce o tym nie wspomina. Specyficzna dla Pythona sk\u0142adnia w filmach mo\u017ce stanowi\u0107 wyzwanie dla niekt\xf3rych u\u017cytkownik\xf3w. Dyskusja ocenia nacisk kursu na regresj\u0119 logistyczn\u0105 i perceptron. Uczestnicy uznali kurs za \u0142atwy do zrozumienia i polecaj\u0105 inne kursy dla pocz\u0105tkuj\u0105cych. Niekt\xf3rzy u\u017cytkownicy kwestionuj\u0105 minimaln\u0105 wiedz\u0119 programist\xf3w internetowych, a jeden u\u017cytkownik ma teori\u0119 na temat zwi\u0105zku ML z algebr\u0105 Hopfa."]}),"\n",(0,n.jsx)(i.h2,{id:"sztuczka-na-osi\u0105gni\u0119cie-przep\u0142ywu-zostaw-swoj\u0105-prac\u0119-zepsut\u0105",children:"Sztuczka na osi\u0105gni\u0119cie przep\u0142ywu: Zostaw swoj\u0105 prac\u0119 zepsut\u0105"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://census.dev/blog/an-on-ramp-to-flow",children:"Original"}),'.\nArtyku\u0142 omawia trudno\u015bci z wej\u015bciem w stan "przep\u0142ywu" w zadaniach in\u017cynierskich i podaje sztuczk\u0119 na ponowne wej\u015bcie w przep\u0142yw. Autor sugeruje pozostawienie swojej pracy w stanie, kt\xf3ry jest ewidentnie zepsuty, ale \u0142atwy do naprawienia przed odej\u015bciem. Pozwala to na jasny punkt wyj\u015bcia podczas powrotu do pracy, tworz\u0105c impet i pewno\u015b\u0107 siebie. Artyku\u0142 przyznaje, \u017ce to podej\u015bcie mo\u017ce nie by\u0107 uniwersalne lub mo\u017cliwe do zastosowania w ustawieniach zespo\u0142owych, ale zaprasza do wyra\u017cenia opinii na temat innych sztuczek. Jest te\u017c kr\xf3tka wzmianka o Census Engineering i mo\u017cliwo\u015bciach zatrudnienia.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35456059",children:"Discussion Service"}),'.\nU\u017cytkownicy Discussion Service dziel\u0105 si\u0119 wskaz\xf3wkami dotycz\u0105cymi osi\u0105gania stanu flow poprzez pozostawianie niedoko\u0144czonej pracy, w tym metod\u0105 "parkowania twarz\u0105 w d\xf3\u0142". Pewien dyrektor in\u017cynierski wdro\u017cy\u0142 ko\u0144czenie pracy o 18:00, aby unikn\u0105\u0107 wypalenia, ale zako\u0144czy\u0142 to z powodu presenteeism. U\u017cytkownicy dyskutuj\u0105 o korzy\u015bciach i zagro\u017ceniach wynikaj\u0105cych z rygorystycznych zasad dotycz\u0105cych czasu pracy i zmiany kultury pracy. Niekt\xf3rzy dziel\u0105 si\u0119 wskaz\xf3wkami dotycz\u0105cymi produktywno\u015bci, takimi jak zapisywanie kolejnych krok\xf3w i praktykowanie TDD. Pozostawienie kodu w "zepsutym" stanie mo\u017ce pom\xf3c w p\xf3\u017aniejszym wznowieniu, ale ma mieszane rezultaty.']}),"\n",(0,n.jsx)(i.h2,{id:"czy-pami\u0119\u0107-ram-jest-wymazywana-przed-u\u017cyciem-w-innym-kontenerze-lxc",children:"Czy pami\u0119\u0107 RAM jest wymazywana przed u\u017cyciem w innym kontenerze LXC?"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://security.stackexchange.com/questions/269507/is-ram-wiped-before-use-in-another-lxc-container",children:"Original"}),".\nPost na Information Security Stack Exchange pyta, czy RAM jest wymazywany przed u\u017cyciem w innym kontenerze LXC, co prowadzi do dyskusji na temat RAM-overprovisioning w LXC, z jednym u\u017cytkownikiem komentuj\u0105cym, \u017ce pami\u0119\u0107 przydzielona do poprzedniego procesu w kontenerze jest czyszczona. Post na Hacker News zag\u0142\u0119bia si\u0119 dalej, omawiaj\u0105c biblioteki wsp\xf3\u0142dzielone i ochron\u0119 przestrzeni nazw u\u017cytkownika, a odpowied\u017a wyja\u015bnia, \u017ce strony s\u0105 puste przed alokacj\u0105, over-provisioning nie powoduje dzielenia, a pami\u0119\u0107 LXC jest przydzielana procesom za po\u015brednictwem przestrzeni nazw, ale procesy s\u0105 oddzielone od zasob\xf3w hosta. Na koniec zauwa\u017cono, \u017ce zarz\u0105dzanie pami\u0119ci\u0105 oparte na glibc nie obejmuje czyszczenia, a wolne strony mog\u0105 zawiera\u0107 dane."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35451863",children:"Discussion Service"}),".\nU\u017cytkownicy na Hacker News dyskutowali o skuteczno\u015bci i konieczno\u015bci automatycznego zerowania pami\u0119ci w Linuksie, przy czym niekt\xf3rzy sugerowali alternatywne metody oczyszczania nieu\u017cywanej pami\u0119ci. Jeden z u\u017cytkownik\xf3w zwr\xf3ci\u0142 uwag\u0119, \u017ce problem le\u017cy w konstrukcji wywo\u0142ania systemowego fork() w systemie UNIX, a wiele program\xf3w intensywnie wykorzystuj\u0105cych pami\u0119\u0107 wci\u0105\u017c boryka si\u0119 z problemami OOM. Inne komentarze omawiaj\u0105 r\xf3\u017cnice pomi\u0119dzy overcommit i non-overcommit alokacj\u0105 pami\u0119ci w Linuksie oraz znaczenie ustalania limit\xf3w. Artyku\u0142 dostarcza zniuansowanych perspektyw na alokacj\u0119 pami\u0119ci w Linuksie i jest skierowany do ekspert\xf3w w tej dziedzinie."]}),"\n",(0,n.jsx)(i.h2,{id:"perspektywa-open-source-webassembly-powered-bi",children:"Perspektywa: Open Source WebAssembly-Powered BI"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://perspective.finos.org/",children:"Original"}),".\nPerspective jest interaktywnym komponentem do analizy i wizualizacji danych, zaprojektowanym dla strumieniowych i du\u017cych zbior\xf3w danych z konfigurowalnymi raportami, pulpitami i notatnikami. Posiada on wydajny pod wzgl\u0119dem pami\u0119ci silnik zapyta\u0144 strumieniowych w C++ i Pythonie oraz UI opakowany jako element niestandardowy zasilany przez WebAssembly lub WebSocket. UI zawiera interaktywne pulpity, kt\xf3re mog\u0105 by\u0107 zintegrowane z dowoln\u0105 aplikacj\u0105 internetow\u0105. Perspective.js opiera si\u0119 na WebAssembly i Apache Arrow dla wydajno\u015bci zbli\u017conej do desktopowej w przegl\u0105darce. PerspectivePython implementuje API Perspective bezpo\u015brednio w Pythonie do bada\u0144 lub produkcji. Istniej\u0105 zwirtualizowane i skalowalne wid\u017cety, a projekt jest dost\u0119pny na GitHubie z przewodnikami dla u\u017cytkownik\xf3w i programist\xf3w."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35455850",children:"Discussion Service"}),".\nOpen-source'owe narz\u0119dzie BI oparte na WebAssembly - Perspective - chwalone za du\u017c\u0105 funkcjonalno\u015b\u0107, mimo problem\xf3w z wydajno\u015bci\u0105: sugerowane rozwi\u0105zania obejmuj\u0105 u\u017cycie bardziej lekkiej opcji. Tw\xf3rcy Perspective pracuj\u0105 nad popraw\u0105 wydajno\u015bci i kompatybilno\u015bci z urz\u0105dzeniami mobilnymi. Pojawi\u0142y si\u0119 pewne obawy dotycz\u0105ce wsparcia dla Firefoxa i dost\u0119pno\u015bci/nieprzyjaznego dla klawiatury projektu. Om\xf3wiono ograniczenia Sciter, biblioteki Tauri postrzegane jako potencjalnie u\u017cyteczne. Poprawa wydajno\u015bci potrzebna dla projektu Perspective."]}),"\n",(0,n.jsx)(i.h2,{id:"grid-world",children:"Grid World"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://alex.miller.garden/grid-world/",children:"Original"}),'.\nGrid World" Alexandra Millera bada rol\u0119 siatki w jego \u017cyciu od dzieci\u0144stwa do doros\u0142o\u015bci, w\u0142\u0105czaj\u0105c w to jej wp\u0142yw w technologii, sztuce i nawigacji. Artyku\u0142 porusza kwesti\u0119 mocy, jak\u0105 siatki maj\u0105 w mapowaniu i kontrolowaniu przestrzeni, co wida\u0107 w grach takich jak Battleship i Chess. Siatka staje si\u0119 centralnym punktem \u0142\u0105cz\u0105cym osobiste do\u015bwiadczenia Millera, pokazuj\u0105c jak staje si\u0119 ona cz\u0119\u015bci\u0105 naszego \u017cycia. Miller stworzy\u0142 siatk\u0119 dla The HTML Review w 2023 roku.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35455770",children:"Discussion Service"}),".\nU\u017cytkownicy Discussion Service s\u0105 zafascynowani wyj\u0105tkowym mistrzostwem i kunsztem Grid World w web design & development oraz jego wp\u0142ywem na percepcj\u0119. Artyku\u0142 bada struktur\u0119 siatki do naszych wspomnie\u0144 i \u015bwiata, z towarzysz\u0105cymi wizualizacjami pixel art. Komentarze zauwa\u017caj\u0105 zwi\u0105zek z neuronauk\u0105 z kom\xf3rkami siatki, jednocze\u015bnie podnosz\u0105c krytyk\u0119 na temat racjonalizacji i kocu siatki na naturze. Jeden z u\u017cytkownik\xf3w uwa\u017ca, \u017ce trudno jest udoskonali\u0107 wizualne aspekty projektu osobistego. U\u017cytkownicy omawiaj\u0105 wzory siatki w Queens i histori\u0119 stoj\u0105c\u0105 za tymi wzorami. U\u017cytkownik Discussion Service dzieli si\u0119 spostrze\u017ceniami na temat zgodno\u015bci siatki ulic w NYC. Dekoracja przypominaj\u0105ca st\xf3\u0142 generuje s\u0142abo o\u015bwietlone mesy, jednocze\u015bnie ewoluuj\u0105c w czasie, zbudowana ze zwyk\u0142ym javascriptem bez \u017cadnych bibliotek dla zabawnych \u0107wicze\u0144 technicznych."]}),"\n",(0,n.jsx)(i.h2,{id:"tokenizer-openai",children:"Tokenizer OpenAI"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://platform.openai.com/tokenizer",children:"Orygina\u0142"}),".\nAPI OpenAI jest technologi\u0105, kt\xf3ra wymaga w\u0142\u0105czenia JavaScript."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35453400",children:"Discussion Service"}),".\nOpenAI wyda\u0142o nowy tokenizer, aby lepiej zrozumie\u0107 modele GPT. Tokenizer dzieli tekst na jednostki pods\u0142owia dla efektywnego przetwarzania, ale brakuje im nieod\u0142\u0105cznego znaczenia. U\u017cytkownicy Discussion Service omawiaj\u0105 ograniczenia narz\u0119dzia, takie jak grupowanie na podstawie spacji i zabieg\xf3w kapitalizacji. Kodowania tworzone za pomoc\u0105 par bajt\xf3w cz\u0119sto nie s\u0105 dobrze dostosowane do j\u0119zyk\xf3w niedostatecznie reprezentowanych. OpenAI pobiera op\u0142aty za token ze wzgl\u0119du na dzia\u0142anie modelu oparte na tokenach."]}),"\n",(0,n.jsx)(i.h2,{id:"tabloid---j\u0119zyk-programowania-nag\u0142\xf3wk\xf3w-clickbaitowych",children:"Tabloid - J\u0119zyk programowania nag\u0142\xf3wk\xf3w clickbaitowych"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://tabloid-thesephist.vercel.app/",children:"Orygina\u0142"}),".\nTabloid to nowy j\u0119zyk programowania stworzony do generowania \u015bmiesznych i wartych klikni\u0119cia nag\u0142\xf3wk\xf3w, przypominaj\u0105cych te widziane w tabloidach. J\u0119zyk wykorzystuje po\u0142\u0105czenie przetwarzania j\u0119zyka naturalnego, uczenia maszynowego i crowd-sourcingu do tworzenia nag\u0142\xf3wk\xf3w z clickbaitycznymi wzorcami j\u0119zykowymi. To zabawny i rozrywkowy j\u0119zyk, kt\xf3ry nie s\u0142u\u017cy \u017cadnemu celowi, ale jest doskona\u0142ym przyk\u0142adem tego, jak programowanie mo\u017ce by\u0107 zar\xf3wno u\u017cyteczne, jak i zabawne. Tw\xf3rca Tabloidu planuje wykorzysta\u0107 go do stworzenia platformy, kt\xf3ra pozwoli ka\u017cdemu tworzy\u0107 swoje clickbaitowe nag\u0142\xf3wki. U\u017cytkownicy Discussion Service uwa\u017caj\u0105 to narz\u0119dzie za interesuj\u0105ce i przydatne do zrozumienia przetwarzania j\u0119zyka naturalnego."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35447580",children:"Discussion Service"}),'.\nNiedawno na Hacker News pojawi\u0142 si\u0119 projekt o nazwie Tabloid - The Clickbait Headline Programming Language. Projekt jest fascynuj\u0105cy, napisany przez autora, kt\xf3ry twierdzi, \u017ce napisa\u0142 inne j\u0119zyki, kt\xf3re s\u0105 prawdopodobnie bardziej u\u017cyteczne. U\u017cytkownik Discussion Service zamie\u015bci\u0142 program w Tabloid, kt\xf3ry pobiera pi\u0119\u0107 liczb i zwraca produkt trzech pierwszych liczb plus produkt dw\xf3ch ostatnich. Autor jest osob\u0105, kt\xf3ra wys\u0142a\u0142a wiele interesuj\u0105cych projekt\xf3w, nawet u\u017cywaj\u0105c Oak\'a do zbudowania mi\u0119dzy innymi osobistej infrastruktury programowej. Inny u\u017cytkownik Discussion Service skomentowa\u0142, \u017ce pisanie wszystkiego od zera jest najbardziej op\u0142acalne dla samotnych programist\xf3w, ale nie dla zespo\u0142\xf3w, gdzie lepiej jest i\u015b\u0107 z "nud\u0105".']}),"\n",(0,n.jsx)(i.h2,{id:"gpt4-symuluje-serwer-ftp-na-ftpdisneycom",children:"GPT4 symuluje serwer FTP na ftp.disney.com"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.filestash.app/2023/04/01/chat-gpt-acting-as-a-ftp-server/",children:"Original"}),".\nChat GPT-4 potrafi symulowa\u0107 serwer FTP dla Disneya, u\u017cywaj\u0105c podstawowego narz\u0119dzia ftp cli i przychodz\u0105cych podpowiedzi, aby wykona\u0107 polecenia jak prawdziwy u\u017cytkownik. Symulowany serwer zawiera ekskluzywn\u0105 zawarto\u015b\u0107 Disneya w folderach takich jak filmy, \u015bcie\u017cki d\u017awi\u0119kowe i tapety, a GPT-4 udowadnia, \u017ce potrafi porusza\u0107 si\u0119 po lokalnych i zdalnych systemach plik\xf3w. Nowa technologia spisuje si\u0119 dobrze, przekraczaj\u0105c oczekiwania i demonstruj\u0105c swoj\u0105 zdolno\u015b\u0107 do tworzenia atrakcyjnych tre\u015bci dla entuzjast\xf3w Disneya. Artyku\u0142 wskazuje na przysz\u0142e zastosowania GPT-4 we wtyczkach do interpretera kodu, kt\xf3re umo\u017cliwiaj\u0105 dost\u0119p do ob\u0142\u0105kanych serwer\xf3w z poziomu klient\xf3w FTP."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35450315",children:"Discussion Service"}),'.\nArtyku\u0142 na Hacker News omawia GPT4 symuluj\u0105ce serwer FTP pod adresem ftp.disney.com. U\u017cytkownicy debatuj\u0105, czy mo\u017cna to uzna\u0107 za "halucynacje", pomimo mo\u017cliwo\u015bci symulacji lub "halucynacji" przez AI. Dok\u0142adno\u015b\u0107 odpowiedzi generowanych przez AI i postrzeganie tych danych wyj\u015bciowych jako "halucynacji" s\u0105 r\xf3wnie\u017c punktami dyskusji. Inne poruszane tematy to: potencja\u0142 bezwarto\u015bciowo\u015bci samodzielnie wygenerowanych film\xf3w lub program\xf3w telewizyjnych, rola przestrzeni ukrytej i j\u0119zyka w LLM, wp\u0142yw technologii na spo\u0142ecze\u0144stwo oraz ograniczenia obecnych mo\u017cliwo\u015bci AI. Niekt\xf3rzy u\u017cytkownicy przestrzegaj\u0105 przed nadinterpretacj\u0105 mo\u017cliwo\u015bci SI i zauwa\u017caj\u0105, \u017ce jej ograniczenia s\u0105 cz\u0119sto pomijane.']}),"\n",(0,n.jsx)(i.h2,{id:"u\u017cycie-mmap-aby-llama-\u0142adowa\u0142a-si\u0119-szybciej",children:"U\u017cycie mmap, aby LLaMA \u0142adowa\u0142a si\u0119 szybciej"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://justine.lol/mmap/",children:"Original"}),".\nLLaMA u\u017cywa mmap() do 100x szybszego \u0142adowania modeli, zwi\u0119ksza stabilno\u015b\u0107 pami\u0119ci RAM i umo\u017cliwia jednoczesne dzia\u0142anie wielu proces\xf3w. U\u017cytkownicy Linuksa otrzymuj\u0105 100x popraw\u0119, a Windows i MacOS - 10x. Nowy mmap() loader jest teraz dost\u0119pny na GitHubie na licencji MIT. Anonimowy wsp\xf3\u0142pracownik @Slaren doda\u0142 obs\u0142ug\u0119 mmap() do LLaMA-7B, umo\u017cliwiaj\u0105c b\u0142yskawiczne \u0142adowanie bez zmiany formatu pliku. Nowy format pliku wyr\xf3wnuje tensory na 32-bajtowej granicy. Post bada potencjaln\u0105 popraw\u0119 wykorzystania dysku i zak\u0142\xf3cenia wydajno\u015bci. Justine Tunney pisze o Twitterze i Githubie w standardowych narz\u0119dziach, skierowanych do ekspert\xf3w w tej dziedzinie. Jest jasna i zwi\u0119z\u0142a, bez stronniczo\u015bci i o\u015bwiadcze\u0144 politycznych lub religijnych. U\u017cytkownik Discussion Service komentuje, \u017ce post Tunney jest \u015bwietnym \u017ar\xf3d\u0142em wiedzy."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35455930",children:"Discussion Service"}),".\nU\u017cycie mmap do przyspieszenia \u0142adowania LLaMA jest g\u0142\xf3wnym tematem artyku\u0142u, pomimo dramatu wok\xf3\u0142 atrybucji i kwestii technicznych w sekcji komentarzy. Om\xf3wione s\u0105 zalety i wady mmap, a tak\u017ce techniczne zalety LLaMA.cpp Facebooka. U\u017cytkownicy omawiaj\u0105 u\u017cyteczno\u015b\u0107 zmian w LLaMA oraz zalety i wady r\xf3\u017cnych funkcji, dostarczaj\u0105c cennych spostrze\u017ce\u0144 czytelnikom zainteresowanym nauk\u0105 o AI i implementacj\u0105 modeli. Post podkre\u015bla podej\u015bcie in\u017cynierii systemowej do problemu i trend obejmuj\u0105cy zastrze\u017cony kod w bibliotekach, generuj\u0105c dyskusj\u0119 na temat wykorzystania Huge Pages i trudno\u015bci w rozwi\u0105zywaniu w\u0105skich garde\u0142 IO. Rewolucyjna poprawa wydajno\u015bci przy u\u017cyciu mmap przyci\u0105gn\u0119\u0142a uwag\u0119 ekspert\xf3w w tej dziedzinie."]})]})}function y(e={}){const{wrapper:i}={...(0,r.R)(),...e.components};return i?(0,n.jsx)(i,{...e,children:(0,n.jsx)(z,{...e})}):z(e)}}}]);